= PetalburgCity_PokemonCenter_1F_EventScript_Woman
lock
faceplayer
msgbox	There are many types of POKéMON.All types have their strengths and weaknesses against other types.Depending on the types of POKéMON, a battle could be easy or hard.
specialvar VAR_RESULT IsStarterInParty
goto_if_eq VAR_RESULT TRUE PetalburgCity_PokemonCenter_1F_EventScript_SayStarterTypeInfo
release
end
= PetalburgCity_PokemonCenter_1F_EventScript_SayStarterTypeInfo
call_if_eq VAR_STARTER_MON 0 PetalburgCity_PokemonCenter_1F_EventScript_SayTreeckoType
call_if_eq VAR_STARTER_MON 1 PetalburgCity_PokemonCenter_1F_EventScript_SayTorchicType
call_if_eq VAR_STARTER_MON 2 PetalburgCity_PokemonCenter_1F_EventScript_SayMudkipType
release
end
= PetalburgCity_PokemonCenter_1F_EventScript_SayMudkipType
msgbox	For example, your MUDKIP is a WATER type.It's strong against the FIRE type.But, it's weak against GRASS-type and ELECTRIC-type POKéMON.
return
= PetalburgCity_PokemonCenter_1F_EventScript_SayTorchicType
msgbox	For example, your TORCHIC is a FIRE type.It's strong against the GRASS and BUG types.But, it's weak against WATER-type POKéMON.
return
= PetalburgCity_PokemonCenter_1F_EventScript_SayTreeckoType
msgbox	For example, your TREECKO is a GRASS type.It's strong against the WATER and GROUND types.But, it's weak against FIRE-type POKéMON.
return
= PetalburgCity_PokemonCenter_1F_EventScript_Youngster
msgbox	When my POKéMON ate an ORAN BERRY, it regained HP!
end
= PetalburgCity_PokemonCenter_1F_EventScript_FatMan
msgbox	That PC-based POKéMON Storage System…Whoever made it must be some kind of a scientific wizard!
end
= ProfileMan_EventScript_Man
lock
faceplayer
goto_if_set FLAG_SYS_CHAT_USED ProfileMan_EventScript_GivenProfileBefore
msgbox	ProfileMan_Text_CollectTrainerProfiles
goto ProfileMan_EventScript_AskToSeeProfile
end
= ProfileMan_EventScript_AskToSeeProfile
msgbox	ProfileMan_Text_MayISeeYourProfile
multichoice 17 6 MULTI_YESNOINFO_2 FALSE
switch VAR_RESULT
case 0 ProfileMan_EventScript_CreateProfile
case 1 ProfileMan_EventScript_DeclineShowProfile
case 2 ProfileMan_EventScript_Info
case MULTI_B_PRESSED ProfileMan_EventScript_DeclineShowProfile
end
= ProfileMan_EventScript_DeclineShowProfile
msgbox	ProfileMan_Text_ImagineYouWouldHaveWonderfulProfile
release
end
= ProfileMan_EventScript_Info
msgbox	ProfileMan_Text_EasyChatExplanation
goto ProfileMan_EventScript_AskToSeeProfile
end
= ProfileMan_EventScript_CreateProfile
msgbox	ProfileMan_Text_LetsSeeItThen
closemessage
setvar VAR_0x8004 EASY_CHAT_TYPE_PROFILE
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 0 ProfileMan_EventScript_CancelShowProfile
goto_if_eq VAR_RESULT 1 ProfileMan_EventScript_ShowProfile
end
= ProfileMan_EventScript_ShowProfile
setvar VAR_0x8004 0
special ShowEasyChatProfile
waitmessage
delay 80
msgbox	ProfileMan_Text_FantasticProfile
release
end
= ProfileMan_EventScript_CancelShowProfile
msgbox	ProfileMan_Text_NotIntoItRightNow
release
end
= ProfileMan_EventScript_GivenProfileBefore
msgbox	ProfileMan_Text_YouHaveWonderfulSmile
goto ProfileMan_EventScript_AskToSeeNewProfile
end
= ProfileMan_EventScript_AskToSeeNewProfile
msgbox	ProfileMan_Text_MayISeeYourNewProfile
multichoice 17 6 MULTI_YESNOINFO_2 FALSE
switch VAR_RESULT
case 0 ProfileMan_EventScript_CreateNewProfile
case 1 ProfileMan_EventScript_DeclineNewProfile
case 2 ProfileMan_EventScript_InfoNewProfile
case MULTI_B_PRESSED ProfileMan_EventScript_DeclineNewProfile
end
= ProfileMan_EventScript_DeclineNewProfile
msgbox	ProfileMan_Text_LikeProfileWayItIs
release
end
@ Unused
goto ProfileMan_EventScript_Ret
= ProfileMan_EventScript_Ret
return
= ProfileMan_EventScript_InfoNewProfile
msgbox	ProfileMan_Text_EasyChatExplanation
goto ProfileMan_EventScript_AskToSeeNewProfile
end
= ProfileMan_EventScript_CreateNewProfile
msgbox	ProfileMan_Text_EvenBetterThanLastProfile
closemessage
setvar VAR_0x8004 EASY_CHAT_TYPE_PROFILE
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 0 ProfileMan_EventScript_CancelShowProfile
goto_if_eq VAR_RESULT 1 ProfileMan_EventScript_ShowProfile
end
= PetalburgCity_PokemonCenter_1F_EventScript_Nurse
setvar VAR_0x800B LOCALID_PETALBURG_NURSE
call Common_EventScript_PkmnCenterNurse
waitmessage
waitbuttonpress
release
end
= Common_EventScript_PkmnCenterNurse
lock
faceplayer
setvar VAR_0x8004 0
specialvar VAR_RESULT CountPlayerTrainerStars
goto_if_eq VAR_RESULT 4 EventScript_PkmnCenterNurse_GoldCard
msgbox	gText_WouldYouLikeToRestYourPkmn
goto_if_eq VAR_RESULT YES EventScript_PkmnCenterNurse_HealPkmn
goto_if_eq VAR_RESULT NO EventScript_PkmnCenterNurse_Goodbye
end
= EventScript_PkmnCenterNurse_Goodbye
message gText_WeHopeToSeeYouAgain
return
@ VAR_0x8004 is 1 when player has Gold Card; jumps are identical
goto EventScript_PkmnCenterNurse_HealPkmn
= EventScript_PkmnCenterNurse_HealPkmn
incrementgamestat GAME_STAT_USED_POKECENTER
call_if_eq VAR_0x8004 0 EventScript_PkmnCenterNurse_IllTakeYourPkmn
call_if_eq VAR_0x8004 1 EventScript_PkmnCenterNurse_IllTakeYourPkmn2
waitmessage
call EventScript_PkmnCenterNurse_TakeAndHealPkmn
goto_if_unset FLAG_POKERUS_EXPLAINED EventScript_PkmnCenterNurse_CheckPokerus
goto EventScript_PkmnCenterNurse_CheckTrainerHillAndUnionRoom
end
= EventScript_PkmnCenterNurse_CheckTrainerHillAndUnionRoom
specialvar VAR_RESULT PlayerNotAtTrainerHillEntrance
goto_if_eq VAR_RESULT 0 EventScript_PkmnCenterNurse_ReturnPkmn
specialvar VAR_RESULT BufferUnionRoomPlayerName
copyvar VAR_0x8008 VAR_RESULT
goto_if_eq VAR_0x8008 0 EventScript_PkmnCenterNurse_ReturnPkmn
goto_if_eq VAR_0x8008 1 EventScript_PkmnCenterNurse_PlayerWaitingInUnionRoom
end
@ VAR_0x8004 is 1 when player has Gold Card
goto EventScript_PkmnCenterNurse_ReturnPkmn
= EventScript_PkmnCenterNurse_ReturnPkmn
goto_if_eq VAR_0x8004 1 EventScript_PkmnCenterNurse_ReturnPkmn2
message gText_RestoredPkmnToFullHealth
waitmessage
applymovement VAR_0x800B Movement_PkmnCenterNurse_Bow
waitmovement 0
message gText_WeHopeToSeeYouAgain
return
= EventScript_PkmnCenterNurse_ReturnPkmn2
message gText_ThankYouForWaiting
waitmessage
applymovement VAR_0x800B Movement_PkmnCenterNurse_Bow
waitmovement 0
message gText_WeHopeToSeeYouAgain2
return
= EventScript_PkmnCenterNurse_PlayerWaitingInUnionRoom
goto_if_set FLAG_NURSE_UNION_ROOM_REMINDER EventScript_PkmnCenterNurse_ReturnPkmn
msgbox	gText_RestoredPkmnToFullHealth
setflag FLAG_NURSE_UNION_ROOM_REMINDER
message CableClub_Text_PlayerIsWaiting
waitmessage
applymovement VAR_0x800B Movement_PkmnCenterNurse_Bow
waitmovement 0
message gText_WeHopeToSeeYouAgain
return
= EventScript_PkmnCenterNurse_CheckPokerus
specialvar VAR_RESULT IsPokerusInParty
goto_if_eq VAR_RESULT TRUE EventScript_PkmnCenterNurse_ExplainPokerus
goto_if_eq VAR_RESULT FALSE EventScript_PkmnCenterNurse_CheckTrainerHillAndUnionRoom
end
= EventScript_PkmnCenterNurse_ExplainPokerus
message gText_PokerusExplanation
setflag FLAG_POKERUS_EXPLAINED
return
= EventScript_PkmnCenterNurse_TakeAndHealPkmn
applymovement VAR_0x800B Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
dofieldeffect FLDEFF_POKECENTER_HEAL
waitfieldeffect FLDEFF_POKECENTER_HEAL
applymovement VAR_0x800B Common_Movement_WalkInPlaceFasterDown
waitmovement 0
special HealPlayerParty
return
= EventScript_PkmnCenterNurse_IllTakeYourPkmn2
message gText_IllTakeYourPkmn2
return
= EventScript_PkmnCenterNurse_IllTakeYourPkmn
message gText_IllTakeYourPkmn
return
= EventScript_PkmnCenterNurse_GoldCard
goto_if_set FLAG_NURSE_MENTIONS_GOLD_CARD EventScript_PkmnCenterNurse_AskForUsual
setflag FLAG_NURSE_MENTIONS_GOLD_CARD
msgbox	gText_WelcomeCutShort
playse SE_PIN
applymovement VAR_0x800B Common_Movement_ExclamationMark
waitmovement 0
applymovement VAR_0x800B Common_Movement_Delay48
waitmovement 0
msgbox	gText_NoticesGoldCard
goto_if_eq VAR_RESULT YES EventScript_PkmnCenterNurse_GoldCardHealPkmn
message gText_WeHopeToSeeYouAgain2
return
= EventScript_PkmnCenterNurse_GoldCardHealPkmn
setvar VAR_0x8004 1
goto EventScript_PkmnCenterNurse_HealPkmn
end
= EventScript_PkmnCenterNurse_AskForUsual
msgbox	gText_YouWantTheUsual
goto_if_eq VAR_RESULT YES EventScript_PkmnCenterNurse_GoldCardHealPkmn
message gText_WeHopeToSeeYouAgain2
return
